/**
 * Beamer's real colours, MEASURED — do not hand-edit.
 *
 * Generated by the procedure in `tools/theme-colours.md`: each theme is compiled with
 * `\usebeamercolor` + `\extractcolorspec` + `\typeout`, so these are the values beamer
 * itself resolves, not an approximation of them.
 *
 * This replaced a derivation that mixed every colour from a single hand-written
 * `structure` hex per theme. That was wrong in ways nobody could see without compiling:
 * AnnArbor's frame title is Michigan maize `#fff200` and the canvas drew it navy;
 * CambridgeUS's is light grey `#f2f2f2` and the canvas drew it maroon; Madrid's footline
 * ran light-dark-light where beamer runs it dark-to-light.
 *
 * Only the four themes that cannot compile here (Arguelles, CleanEasy, focus, trigon —
 * all missing font packages) have no entry, and those fall back to the derivation.
 *
 * FORMAT. One string per theme. Fields in `MEASURED_FIELDS` order, separated by a space;
 * within a field, `fg,bg` as six-digit hex without the `#`, either side empty when beamer
 * defines no such colour. Encoded rather than spelled out because this is generated data:
 * 35 themes x 24 fields x 2 colours is 1680 values, and a readable object literal of that
 * is four times the size for no benefit at a call site that never reads it directly.
 */

export const MEASURED_FIELDS = [
  'normalText', 'structure', 'alertedText', 'frametitle', 'title', 'subtitle',
  'author', 'institute', 'date', 'blockTitle', 'blockBody', 'blockTitleAlerted',
  'blockBodyAlerted', 'blockTitleExample', 'blockBodyExample', 'palettePrimary',
  'paletteSecondary', 'paletteTertiary', 'sectionInHeadFoot', 'authorInHeadFoot',
  'titleInHeadFoot', 'dateInHeadFoot', 'backgroundCanvas', 'sidebar',
] as const;

export type MeasuredField = (typeof MEASURED_FIELDS)[number];

/** A foreground/background pair. Either may be absent. */
export interface MeasuredPair {
  fg?: string;
  bg?: string;
}

export type MeasuredTheme = Partial<Record<MeasuredField, MeasuredPair>>;

