/* eslint-enable max-len */

function decode(row: string): MeasuredTheme {
  const out: MeasuredTheme = {};
  const parts = row.split(' ');
  MEASURED_FIELDS.forEach((field, i) => {
    const raw = parts[i];
    if (raw === undefined) return;
    const [fg, bg] = raw.split(',');
    const pair: MeasuredPair = {};
    if (fg) pair.fg = `#${fg}`;
    if (bg) pair.bg = `#${bg}`;
    if (pair.fg !== undefined || pair.bg !== undefined) out[field] = pair;
  });
  return out;
}

/** Decoded once at load; 35 small objects, so eager is simpler than lazy. */
export const MEASURED: Readonly<Record<string, MeasuredTheme>> = Object.fromEntries(
  Object.entries(RAW).map(([theme, row]) => [theme, decode(row)]),
);

/** True when this theme's colours came from the engine rather than from derivation. */
export function hasMeasuredColors(theme: string): boolean {
  return theme in MEASURED;
}
